using Microsoft.AspNetCore.Authorization;using Microsoft.AspNetCore.Mvc;using MicroEMR.Web.Models.PatientChartAlerts;using MicroEMR.Web.Services.PatientChartAlerts;namespace MicroEMR.Web.Controllers;[Authorize]public sealed class PatientChartAlertsController:Controller{private readonly IPatientChartAlertApiClient c;public PatientChartAlertsController(IPatientChartAlertApiClient x)=>c=x;[HttpGet]public async Task<IActionResult>List(Guid patientUid,string status="Active",CancellationToken t=default)=>Json(new{success=true,alerts=await c.List(patientUid,status,t)});[HttpPost,ValidateAntiForgeryToken]public async Task<IActionResult>Create(SavePatientChartAlertViewModel x,CancellationToken t){if(!ModelState.IsValid)return BadRequest(new{success=false,message="Alert title is required."});return Json(new{success=true,alert=await c.Create(x.PatientUid,x,t)});}[HttpPost,ValidateAntiForgeryToken]public async Task<IActionResult>Update(UpdatePatientChartAlertViewModel x,CancellationToken t){if(!ModelState.IsValid)return BadRequest(new{success=false,message="Invalid alert."});try{return Json(new{success=true,alert=await c.Update(x.PatientUid,x.PatientChartAlertUid,x,t)});}catch(HttpRequestException e)when(e.StatusCode==System.Net.HttpStatusCode.Conflict){return Conflict(new{success=false,message=e.Message});}}[HttpPost,ValidateAntiForgeryToken]public async Task<IActionResult>Resolve(ResolvePatientChartAlertViewModel x,CancellationToken t)=>Json(new{success=true,alert=await c.Resolve(x.PatientUid,x.PatientChartAlertUid,x,t)});}
